mapper.select:
SELECT id, household_id, payer_user_id, category_id, account_id, amount, purpose, memo, expense_date,
       include_in_household_total, created_at
FROM expenses
WHERE household_id = #{householdId}
  AND payer_user_id = #{payerUserId}

    AND category_id = #{categoryId}

ORDER BY expense_date DESC, id DESC
